237	// buildCondensedTranscriptFromCodex converts Codex rollout JSONL into the compact
238	// transcript format, then reuses the shared transcript condensation logic.
239	func buildCondensedTranscriptFromCodex(content redact.RedactedBytes) ([]Entry, error) {
240		compacted, err := compact.Compact(content, compact.MetadataFields{
241			Agent:      "codex",
242			CLIVersion: "summarize",
243		})
244		if err != nil {
245			return nil, fmt.Errorf("failed to compact Codex transcript: %w", err)
246		}
247	
248		type compactUserTextBlock struct {
249			Text string `json:"text"`
250		}
251		type compactAssistantBlock struct {
252			Type  string          `json:"type"`
253			Text  string          `json:"text,omitempty"`
254			Name  string          `json:"name,omitempty"`
255			Input json.RawMessage `json:"input,omitempty"`
256		}
257		type compactLine struct {
258			Type    string          `json:"type"`
259			Content json.RawMessage `json:"content"`
260		}
261	
262		var entries []Entry
263		for _, lineBytes := range splitCompactJSONL(compacted) {
264			var line compactLine
265			if err := json.Unmarshal(lineBytes, &line); err != nil {
266				continue
267			}
268	
269			switch line.Type {
270			case transcript.TypeUser:
271				var blocks []compactUserTextBlock
272				if err := json.Unmarshal(line.Content, &blocks); err != nil {
273					continue
274				}
275				for _, block := range blocks {
276					if block.Text != "" {
277						entries = append(entries, Entry{
278							Type:    EntryTypeUser,
279							Content: block.Text,
280						})
281					}
282				}
283			case transcript.TypeAssistant:
284				var blocks []compactAssistantBlock
285				if err := json.Unmarshal(line.Content, &blocks); err != nil {
286					continue
287				}
288				for _, block := range blocks {
289					switch block.Type {
290					case transcript.ContentTypeText:
291						if block.Text != "" {
292							entries = append(entries, Entry{
293								Type:    EntryTypeAssistant,
294								Content: block.Text,
295							})
296						}
297					case transcript.ContentTypeToolUse:
298						var input map[string]interface{}
299						if err := json.Unmarshal(block.Input, &input); err != nil {
300							input = nil
301						}
302						entries = append(entries, Entry{
303							Type:       EntryTypeTool,
304							ToolName:   block.Name,
305							ToolDetail: extractGenericToolDetail(input),
306						})
307					}
308				}
309			}
310		}
311	
312		return entries, nil
313	}
314	
315	// buildCondensedTranscriptFromDroid parses Droid transcript and extracts a condensed view.
316	func buildCondensedTranscriptFromDroid(redacted redact.RedactedBytes) ([]Entry, error) {
317		droidLines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes(redacted.Bytes(), 0)
318		if err != nil {
319			return nil, fmt.Errorf("failed to parse Droid transcript: %w", err)
320		}
321		return BuildCondensedTranscript(droidLines), nil
322	}
323	
324	// extractOpenCodeToolDetail extracts a detail string from an OpenCode tool's input map.
325	// OpenCode uses camelCase keys (e.g., "filePath" instead of "file_path").
326	func extractOpenCodeToolDetail(input map[string]interface{}) string {
327		for _, key := range []string{"description", "command", "filePath", "path", "pattern"} {
328			if v, ok := input[key].(string); ok && v != "" {
329				return v
330			}
331		}
332		return ""
333	}
334	
335	// extractGenericToolDetail extracts an appropriate detail string from a tool's input/args map.
336	// Checks common fields in order of preference.
337	func extractGenericToolDetail(input map[string]interface{}) string {
338		if input == nil {
339			return ""
340		}
341		for _, key := range []string{"description", "command", "cmd", "file_path", "path", "pattern"} {
342			if v, ok := input[key].(string); ok && v != "" {
343				return v
344			}
345		}
346		return ""
347	}
348	
349	func splitCompactJSONL(data []byte) [][]byte {
350		var lines [][]byte
351		for _, line := range bytes.Split(data, []byte("\n")) {
352			line = bytes.TrimSpace(line)
353			if len(line) > 0 {
354				lines = append(lines, line)
355			}
356		}
357		return lines
358	}
359	
360	// BuildCondensedTranscript extracts a condensed view of the transcript.
361	// It processes user prompts, assistant responses, and tool calls into
362	// a simplified format suitable for LLM summarization.
363	func BuildCondensedTranscript(lines []transcript.Line) []Entry {
364		var entries []Entry
365	
366		for _, line := range lines {
367			switch line.Type {
368			case transcript.TypeUser:
369				if entry := extractUserEntry(line); entry != nil {
370					entries = append(entries, *entry)
371				}
372			case transcript.TypeAssistant:
373				assistantEntries := extractAssistantEntries(line)
374				entries = append(entries, assistantEntries...)
375			}
376		}
377	
378		return entries
379	}
380	
381	// skillContentPrefix identifies user messages that are skill content injections.
382	// These are injected after a Skill tool call and contain the full skill instructions.
383	const skillContentPrefix = "Base directory for this skill:"
384	
385	// extractUserEntry extracts a user entry from a transcript line.
386	// Returns nil if the line doesn't contain a valid user prompt or is skill content.
387	func extractUserEntry(line transcript.Line) *Entry {
388		content := transcript.ExtractUserContent(line.Message)
389		if content == "" {
390			return nil
391		}
392	
393		// Skip skill content injections - these are verbose skill instructions
394		// injected as user messages after Skill tool invocations in Claude Code.
395		// The prefix "Base directory for this skill:" is added by the superpowers
396		// plugin when loading skill content. This filtering reduces transcript noise
397		// since skill content is documentation, not user intent.
398		if strings.HasPrefix(content, skillContentPrefix) {
399			return nil
400		}
401	
402		return &Entry{
403			Type:    EntryTypeUser,
404			Content: content,
405		}
406	}
407	
408	// extractAssistantEntries extracts assistant and tool entries from a transcript line.
409	func extractAssistantEntries(line transcript.Line) []Entry {
410		var msg transcript.AssistantMessage
411		if err := json.Unmarshal(line.Message, &msg); err != nil {
412			return nil
413		}
414	
415		var entries []Entry
416	
417		for _, block := range msg.Content {
418			switch block.Type {
419			case transcript.ContentTypeText:
420				if block.Text != "" {
421					entries = append(entries, Entry{
422						Type:    EntryTypeAssistant,
423						Content: block.Text,
424					})
425				}
426			case transcript.ContentTypeToolUse:
427				var input transcript.ToolInput
428				_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
429	
430				detail := extractToolDetail(block.Name, input)
431	
432				entries = append(entries, Entry{
433					Type:       EntryTypeTool,
434					ToolName:   block.Name,
435					ToolDetail: detail,
436				})
437			}
438		}
439	
440		return entries
441	}
442	
443	// extractToolDetail extracts an appropriate detail string for a tool call.
444	// For tools in minimalDetailTools, only essential identifiers are shown.
445	// For other tools, the full detail chain is used.
446	func extractToolDetail(toolName string, input transcript.ToolInput) string {
447		// For minimal detail tools, extract only the essential identifier
448		if minimalDetailTools[toolName] {
449			switch toolName {
450			case "Skill":
451				return input.Skill
452			case "Read":
453				if input.FilePath != "" {
454					return input.FilePath
455				}
456				return input.NotebookPath
457			case "WebFetch":
458				return input.URL
459			}
460		}
461	
462		// For other tools, use the full detail chain
463		if input.Description != "" {
464			return input.Description
465		}
466		if input.Command != "" {
467			return input.Command
468		}
469		if input.FilePath != "" {
470			return input.FilePath
471		}
472		if input.NotebookPath != "" {
473			return input.NotebookPath
474		}
475		return input.Pattern
476	}
477	
478	// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
479	// The format is:
480	//
481	//	[User] user prompt here
482	//
483	//	[Assistant] assistant response here
484	//
485	//	[Tool] ToolName: description or file path
486	func FormatCondensedTranscript(input Input) string {
487		var sb strings.Builder
488	
489		for i, entry := range input.Transcript {
490			if i > 0 {
491				sb.WriteString("\n")
492			}
493	
494			switch entry.Type {
495			case EntryTypeUser:
496				sb.WriteString("[User] ")
497				sb.WriteString(entry.Content)
498				sb.WriteString("\n")
499			case EntryTypeAssistant:
500				sb.WriteString("[Assistant] ")
501				sb.WriteString(entry.Content)
502				sb.WriteString("\n")
503			case EntryTypeTool:
504				sb.WriteString("[Tool] ")
505				sb.WriteString(entry.ToolName)
506				if entry.ToolDetail != "" {
507					sb.WriteString(": ")
508					sb.WriteString(entry.ToolDetail)
509				}
510				sb.WriteString("\n")
511			}
512		}
513	
514		if len(input.FilesTouched) > 0 {
515			sb.WriteString("\n[Files Modified]\n")
516			for _, file := range input.FilesTouched {
517				fmt.Fprintf(&sb, "- %s\n", file)
518			}
519		}
520	
521		return sb.String()
522	}
