1	package cli
2	
3	import (
4		"bufio"
5		"context"
6		"errors"
7		"fmt"
8		"io"
9		"net/url"
10		"os"
11		"os/exec"
12		"runtime"
13		"time"
14	
15		"github.com/entireio/cli/cmd/entire/cli/api"
16		"github.com/entireio/cli/cmd/entire/cli/auth"
17		"github.com/entireio/cli/cmd/entire/cli/interactive"
18		"github.com/spf13/cobra"
19	)
20	
21	const fallbackDeviceAuthPollInterval = time.Second
22	const defaultSlowDownBackoff = 5 * time.Second
23	const maxPollInterval = 30 * time.Second
24	const maxExpiresIn = 15 * time.Minute
25	const maxTransientErrors = 5
26	
27	// browserOpenFunc is the signature for opening a URL in the user's browser.
28	type browserOpenFunc func(ctx context.Context, url string) error
29	
30	// deviceAuthClient abstracts the auth client so runLogin and waitForApproval can be unit-tested.
31	type deviceAuthClient interface {
32		StartDeviceAuth(ctx context.Context) (*auth.DeviceAuthStart, error)
33		PollDeviceAuth(ctx context.Context, deviceCode string) (*auth.DeviceAuthPoll, error)
34		BaseURL() string
35	}
36	
37	func newLoginCmd() *cobra.Command {
38		var insecureHTTPAuth bool
39	
40		cmd := &cobra.Command{
41			Use:   "login",
42			Short: "Log in to Entire",
43			RunE: func(cmd *cobra.Command, _ []string) error {
44				client := auth.NewClient(nil)
45	
46				if !insecureHTTPAuth {
47					if err := api.RequireSecureURL(client.BaseURL()); err != nil {
48						return fmt.Errorf("base URL check: %w", err)
49					}
50				}
51	
52				return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), client, openBrowser)
53			},
54		}
55	
56		cmd.Flags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
57		if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
58			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
59		}
60	
61		return cmd
62	}
63	
64	func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc) error {
65		start, err := client.StartDeviceAuth(ctx)
66		if err != nil {
67			return fmt.Errorf("start login: %w", err)
68		}
69	
70		fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
71	
72		approvalURL := start.VerificationURI
73	
74		if interactive.CanPromptInteractively() {
75			fmt.Fprintf(outW, "Press Enter to open %s in your browser and enter the generated device code...", approvalURL)
76	
77			// Read from /dev/tty so we get a real keypress and don't consume piped stdin.
78			if err := waitForEnter(ctx); err != nil {
79				return fmt.Errorf("wait for input: %w", err)
80			}
81	
82			fmt.Fprintln(outW)
83	
84			if err := openURL(ctx, approvalURL); err != nil {
85				fmt.Fprintf(errW, "Warning: failed to open browser: %v\n", err)
86				fmt.Fprintf(outW, "Open the approval URL in your browser to continue and enter the generated device code: %s\n", approvalURL)
87			}
88		} else {
89			fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
90		}
91	
92		fmt.Fprintln(outW, "Waiting for approval...")
93	
94		token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, time.Duration(start.Interval)*time.Second, defaultSlowDownBackoff)
95		if err != nil {
96			return fmt.Errorf("complete login: %w", err)
97		}
98	
99		store := auth.NewStore()
100	
101		if err := store.SaveToken(client.BaseURL(), token); err != nil {
102			return fmt.Errorf("save auth token: %w", err)
103		}
104	
105		fmt.Fprintln(outW, "Login complete.")
106		return nil
107	}
108	
109	func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn int, interval, slowDownBackoff time.Duration) (string, error) {
110		expiry := time.Duration(expiresIn) * time.Second
111		if expiry <= 0 || expiry > maxExpiresIn {
112			expiry = maxExpiresIn
113		}
114		deadline := time.Now().Add(expiry)
115		pollInterval := interval
116		if pollInterval <= 0 {
117			pollInterval = fallbackDeviceAuthPollInterval
118		}
119	
120		consecutiveErrors := 0
121	
122		for {
123			if time.Now().After(deadline) {
124				return "", errors.New("device authorization expired")
125			}
126	
127			result, err := poller.PollDeviceAuth(ctx, deviceCode)
128			if err != nil {
129				consecutiveErrors++
130				if consecutiveErrors >= maxTransientErrors {
131					return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
132				}
133				// Transient error — wait and retry.
134				select {
135				case <-ctx.Done():
136					return "", fmt.Errorf("wait for approval: %w", ctx.Err())
137				case <-time.After(pollInterval):
138				}
139				continue
140			}
141			consecutiveErrors = 0
142	
143			switch result.Error {
144			case "":
145				if result.AccessToken == "" {
146					return "", errors.New("device authorization completed without a token")
147				}
148				return result.AccessToken, nil
149			case "authorization_pending":
150				// no-op, will sleep and retry below
151			case "slow_down":
