input.new_string:
// Classify converts raw subprocess signals into *TextGenError. Callers invoke
// Classify *unconditionally* — both on exit 0 and on non-nil runErr — because
// Claude's primary failure mode is exit 0 with is_error:true in the envelope.
//
// Returns nil only when runErr is nil AND (ParseEnvelope is unset OR
// ParseEnvelope reports no structured error). Otherwise returns *TextGenError.
//
// Classification order (first match wins):
//   1. ctx sentinels on runErr (DeadlineExceeded / Canceled) — passthrough,
//      not wrapped in TextGenError.
//   2. CLI-missing detection on runErr — returns CLIMissing. Predicate:
//      errors.As(runErr, &*exec.Error) && errors.Is(execErr.Err, exec.ErrNotFound),
//      OR errors.Is(runErr, exec.ErrNotFound), OR errors.Is(runErr, os.ErrNotExist).
//      (Mirrors 963's isExecNotFound exactly.)
//   3. ParseEnvelope(res.Stdout) if set. When it returns (*EnvelopeResult,
//      true), Classify builds a TextGenError from it — regardless of
//      runErr. This is how Claude's exit-0/is_error case and the envelope-
//      on-non-zero-exit case both reach classification.
//   4. If runErr != nil: HTTP-status baseline substrings in stderr —
//      Auth(401/403), RateLimit(429), Config(400/404).
//   5. If runErr != nil: per-agent phrases in stderr — case-insensitive,
//      first-match-wins in declaration order.
//   6. If runErr != nil: Unknown with Message = trimmed+truncated stderr.
//      When stderr is empty, Message stays empty; the formatter falls back
//      to APIStatus/ExitCode rendering (formatTextGenErrorSuffix).
func (c *Classifier) Classify(ctx context.Context, res ExecResult, runErr error) error

