```go
package cli

import (
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// displayNameFor maps provider AgentName to the proper-noun display used in
// user-facing messages. Keep in sync with syntheticFallback keys.
func displayNameFor(p types.AgentName) string {
	switch p {
	case agent.AgentNameClaudeCode:
		return "Claude"
	case agent.AgentNameCodex:
		return "Codex"
	case agent.AgentNameGemini:
		return "Gemini"
	case agent.AgentNameCursor:
		return "Cursor"
	case agent.AgentNameCopilotCLI:
		return "Copilot"
	default:
		return string(p)
	}
}

// kindPrefix renders the user-facing phrase for a given (Kind, displayName).
// Wording preserves 963's Claude strings verbatim; parameterizing on displayName
// extends that phrasing to other providers uniformly.
func kindPrefix(k agent.TextGenErrorKind, displayName string) string {
	switch k { //nolint:exhaustive // CLIMissing handled separately, Unknown in default
	case agent.TextGenErrorAuth:
		return fmt.Sprintf("%s authentication failed", displayName)
	case agent.TextGenErrorRateLimit:
		return fmt.Sprintf("%s rejected the summary request due to rate limits or quota", displayName)
	case agent.TextGenErrorConfig:
		return fmt.Sprintf("%s rejected the summary request", displayName)
	default:
		return fmt.Sprintf("%s failed to generate the summary", displayName)
	}
}

// syntheticFallback is the narrow table for envelope-present-but-message-empty
// and no-stderr-crash cases. Claude entries reproduce 963's wording verbatim.
// Non-Claude entries use generic phrasing with NO invented subcommands — the
// CLI's own stderr is the source of truth for remediation in the common path.
var syntheticFallback = map[types.AgentName]map[agent.TextGenErrorKind]string{
	agent.AgentNameClaudeCode: {
		agent.TextGenErrorAuth:      "Run `claude login` and retry",
		agent.TextGenErrorRateLimit: "Wait and retry",
		agent.TextGenErrorConfig:    "Check your Claude CLI config and selected model",
	},
	agent.AgentNameCodex: {
		agent.TextGenErrorAuth:      "Check your Codex CLI authentication",
		agent.TextGenErrorRateLimit: "Wait and retry",
		agent.TextGenErrorConfig:    "Check your Codex CLI config and selected model",
	},
	agent.AgentNameGemini: {
		agent.TextGenErrorAuth:      "Check your Gemini CLI authentication",
		agent.TextGenErrorRateLimit: "Wait and retry",
		agent.TextGenErrorConfig:    "Check your Gemini CLI config and selected model",
	},
	agent.AgentNameCursor: {
		agent.TextGenErrorAuth:      "Check your Cursor agent authentication",
		agent.TextGenErrorRateLimit: "Wait and retry",
		agent.TextGenErrorConfig:    "Check your Cursor agent config and selected model",
	},
	agent.AgentNameCopilotCLI: {
		agent.TextGenErrorAuth:      "Check your Copilot CLI authentication",
		agent.TextGenErrorRateLimit: "Wait and retry",
		agent.TextGenErrorConfig:    "Check your Copilot CLI config and selected model",
	},
}

// formatTextGenErrorSuffix preserves 963's "never empty" fallback logic for
// the Unknown kind: prefers Message, then APIStatus (renders as "HTTP N"),
// then ExitCode (negative means abnormal termination), else a sentinel
// indicating no diagnostic signal.
func formatTextGenErrorSuffix(e *agent.TextGenError, displayName string) string {
	if e.Message != "" {
		return ": " + e.Message
	}
	switch {
	case e.APIStatus != 0:
		return fmt.Sprintf(" (%s API returned HTTP %d)", displayName, e.APIStatus)
	case e.ExitCode > 0:
		return fmt.Sprintf(" (%s CLI exited with code %d)", displayName, e.ExitCode)
	case e.ExitCode < 0:
		return fmt.Sprintf(" (%s CLI terminated abnormally — no exit code captured)", displayName)
	default:
		return fmt.Sprintf(" (no diagnostic detail available from %s CLI)", displayName)
	}
}

// renderTextGenError maps a *agent.TextGenError to the user-facing error.
// Non-CLI-missing kinds prefer the CLI's own stderr verbatim; an empty
// Message triggers synthesis fallback (if available) or the diagnostic
// suffix from formatTextGenErrorSuffix.
func renderTextGenError(e *agent.TextGenError) error {
	displayName := displayNameFor(e.Provider)

	if e.Kind == agent.TextGenErrorCLIMissing {
		return fmt.Errorf("%s CLI is not installed or not on PATH", displayName) //nolint:staticcheck // ST1005: proper noun
	}

	prefix := kindPrefix(e.Kind, displayName)
	fallback := syntheticFallback[e.Provider][e.Kind]

	if e.Kind == agent.TextGenErrorUnknown {
		// Unknown always uses the diagnostic suffix pattern (message, then
		// APIStatus, then ExitCode).
		return fmt.Errorf("%s%s", prefix, formatTextGenErrorSuffix(e, displayName)) //nolint:staticcheck // ST1005
	}

	// Auth/RateLimit/Config. Prefer the CLI's own text; always append the
	// short remediation if available, matching 963's Claude format
	// ("Claude authentication failed: <msg>\nRun `claude login` and retry").
	switch {
	case e.Message != "" && fallback != "":
		return fmt.Errorf("%s: %s\n%s", prefix, e.Message, fallback) //nolint:staticcheck // ST1005
	case e.Message != "":
		return fmt.Errorf("%s: %s", prefix, e.Message) //nolint:staticcheck // ST1005
	case fallback != "":
		return fmt.Errorf("%s\n%s", prefix, fallback) //nolint:staticcheck // ST1005
	default:
		return errors.New(prefix)
	}
}
