```go
package claudecode

import (
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// parseClaudeEnvelope wraps parseGenerateTextResponse from response.go and
// translates a Claude CLI "is_error" envelope into an *agent.EnvelopeResult.
// Mirrors 963's classifyEnvelopeError logic (401/403→Auth, 429→RateLimit,
// other 4xx→Config, 0-status with auth phrase→Auth, else Unknown).
//
// Return contract (three cases):
//   a. Parses cleanly and is_error:true → (result, true) with Kind/Message/APIStatus populated.
//   b. Parses cleanly and is_error:false (or missing) → (nil, false). Caller treats as success.
//   c. Parse fails entirely → (synthesized Unknown with "failed to parse…" message, true).
//      Preserves 963's error text at claudecode/generate.go:93. When the
//      subprocess failed with runErr != nil, the caller's phrase classifier
//      still surfaces stderr, because Classify consults ParseEnvelope first
//      and proceeds to HTTP/phrase classification only if ParseEnvelope
//      returns (nil, false) — but for malformed JSON at exit 0 we want this
//      synthesized result to surface the 963 wording.
func parseClaudeEnvelope(stdout []byte) (*agent.EnvelopeResult, bool) {
	result, envelope, parseErr := parseGenerateTextResponse(stdout)
	if parseErr != nil {
		// Case (c): malformed JSON — synthesize a result preserving 963's
		// wording. This fires at exit 0 with garbage stdout; at non-zero
		// exit, the Classifier's caller wants stderr to surface, so we
		// still return (result, true) — the Unknown Kind + explicit
		// Message means the formatter uses Message verbatim, which reads
		// "failed to parse claude CLI response: …" just as 963 did.
		return &agent.EnvelopeResult{
			Kind:    agent.TextGenErrorUnknown,
			Message: fmt.Sprintf("failed to parse claude CLI response: %v", parseErr),
		}, true
	}
	if envelope == nil || !envelope.IsError {
		return nil, false // case (b): success
	}

	// Case (a): structured error. Preserve the result text verbatim (may be
	// empty when Claude returns is_error:true with result:null).
	apiStatus := 0
	if envelope.APIErrorStatus != nil {
		apiStatus = *envelope.APIErrorStatus
	}
	env := &agent.EnvelopeResult{
		Message:   result,
		APIStatus: apiStatus,
	}
	switch {
	case env.APIStatus == 401, env.APIStatus == 403:
		env.Kind = agent.TextGenErrorAuth
	case env.APIStatus == 429:
		env.Kind = agent.TextGenErrorRateLimit
	case env.APIStatus >= 400 && env.APIStatus < 500:
		env.Kind = agent.TextGenErrorConfig
	case env.APIStatus == 0 && containsAuthPhrase(result):
		env.Kind = agent.TextGenErrorAuth
	default:
		env.Kind = agent.TextGenErrorUnknown
	}
	return env, true
}

// containsAuthPhrase duplicates 963's hasAuthPhrase heuristic. We keep the
// two phrases here because they're the Claude envelope fallback specifically;
// the shared Classifier.Phrases for Claude uses the same list for stderr.
var envelopeAuthPhrases = []string{"invalid api key", "not logged in"}

func containsAuthPhrase(s string) bool {
	lower := strings.ToLower(s)
	for _, p := range envelopeAuthPhrases {
		if strings.Contains(lower, p) {
			return true
		}
	}
	return false
}
```

