// providersNeedingSynthesizedRemediation enumerates providers whose CLI
// stderr does NOT carry its own actionable remediation. For these, the
// formatter appends the synthetic fallback line even when Message is
// present (matching 963's Claude wording byte-for-byte).
//
// Providers NOT listed here emit full remediation guidance in stderr
// (Gemini lists 3 env vars, Copilot lists 3 auth paths, Cursor names its
// login command). For them, appending our generic synthesis would be
// noise that obscures the CLI's own authoritative guidance — so we use
// stderr verbatim and skip the fallback when Message is present.
//
// Claude is the singular member today because only it uses an envelope
// (structured JSON) rather than stderr text, and that envelope rarely
// contains remediation.
var providersNeedingSynthesizedRemediation = map[types.AgentName]bool{
	agent.AgentNameClaudeCode: true,
}

// renderTextGenError maps a *agent.TextGenError to the user-facing error.
// Rendering rules by Kind:
//   - CLIMissing: short, provider-agnostic ("<Display> CLI is not installed…").
//   - Unknown: diagnostic-suffix pattern (Message, then APIStatus, then ExitCode).
//   - Auth/RateLimit/Config:
//       * Message present + provider needs synthesis → "<prefix>: <msg>\n<fallback>"
//         (This is Claude's 963 format.)
//       * Message present + provider does NOT need synthesis → "<prefix>: <msg>"
//         (Non-Claude providers: their stderr already contains remediation.)
//       * Message empty + fallback present → "<prefix>\n<fallback>"
//       * Both empty → "<prefix>" (rare; bare kind phrase).
func renderTextGenError(e *agent.TextGenError) error {
	displayName := displayNameFor(e.Provider)

	if e.Kind == agent.TextGenErrorCLIMissing {
		return fmt.Errorf("%s CLI is not installed or not on PATH", displayName) //nolint:staticcheck // ST1005: proper noun
	}

	prefix := kindPrefix(e.Kind, displayName)
	fallback := syntheticFallback[e.Provider][e.Kind]

	if e.Kind == agent.TextGenErrorUnknown {
		return fmt.Errorf("%s%s", prefix, formatTextGenErrorSuffix(e, displayName)) //nolint:staticcheck // ST1005
	}

	needsSynthesis := providersNeedingSynthesizedRemediation[e.Provider]

	switch {
	case e.Message != "" && needsSynthesis && fallback != "":
		// Claude-style: append synthesized remediation after the envelope's
		// own (usually remediation-free) message.
		return fmt.Errorf("%s: %s\n%s", prefix, e.Message, fallback) //nolint:staticcheck // ST1005
	case e.Message != "":
		// Non-synthesis provider with stderr: CLI's guidance stands alone.
		return fmt.Errorf("%s: %s", prefix, e.Message) //nolint:staticcheck // ST1005
	case fallback != "":
		return fmt.Errorf("%s\n%s", prefix, fallback) //nolint:staticcheck // ST1005
	default:
		return errors.New(prefix)
	}
}

