                Provider: c.Provider,
                Cause:    runErr,
            }
        }
    }

    if runErr == nil {
        // Exit-0 success: envelope above was the only path that could produce
        // a non-nil error; everything below requires runErr != nil.
        return nil
    }

    stderrStr := truncateStderr(string(res.Stderr))
    if kind, ok := matchPhrase(stderrStr, httpStatusBaseline); ok {
        return &TextGenError{Kind: kind, Provider: c.Provider, Message: stderrStr, ExitCode: res.ExitCode, Cause: runErr}
    }
    if kind, ok := matchPhrase(stderrStr, c.Phrases); ok {
        return &TextGenError{Kind: kind, Provider: c.Provider, Message: stderrStr, ExitCode: res.ExitCode, Cause: runErr}
    }
    return &TextGenError{Kind: TextGenErrorUnknown, Provider: c.Provider, Message: stderrStr, ExitCode: res.ExitCode, Cause: runErr}
}
